var e=`ဆက်တင်များ`,t=`သင့်စိတ်ကြိုက် ဘဏ်လုပ်ငန်းအတွေ့အကြုံကို ပြင်ဆင်ပါ။`,n=`အသွင်အပြင်`,r=`အပြင်အဆင်`,i=`အလင်းရောင်`,a=`အမှောင်`,o=`စနစ်အတိုင်း`,s=`အသိပေးချက်များ`,c=`App အတွင်း အသိပေးချက်များကို ဖွင့်ရန် သို့မဟုတ် ပိတ်ရန်။`,l=`အသိပေးချက်များ ဖွင့်ထားသည်`,u=`ဘာသာစကား`,d=`သင်နှစ်သက်သော ပြသမည့်ဘာသာစကားကို ရွေးချယ်ပါ။`,f=`English`,p=`မြန်မာ`,m={title:e,description:t,appearance:n,theme:r,lightTheme:i,darkTheme:a,systemTheme:o,notifications:s,notificationsDescription:c,notificationsEnabled:l,language:u,languageDescription:d,english:f,myanmar:p};export{n as appearance,a as darkTheme,m as default,t as description,f as english,u as language,d as languageDescription,i as lightTheme,p as myanmar,s as notifications,c as notificationsDescription,l as notificationsEnabled,o as systemTheme,r as theme,e as title};